// LAB: Compare batching with separate transfers
// Under a serial transfer model, compare one 10,000-byte batch with 100 transfers of 100 bytes. Latency is 10 microseconds and bandwidth is 100 bytes per microsecond; reject nonpositive bandwidth.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    const double latency = 10.0;
    const double bytes_per_us = 100.0;
    const auto time = [&](double bytes) { return latency + bytes / bytes_per_us; };
    std::cout << time(100) << ' ' << time(10000) << '\n';
}

#include <cassert>
#include <iostream>
#include <stdexcept>

double transfer(double bytes, double latency, double bandwidth) {
    if(!(bytes >= 0) || !(latency >= 0) || !(bandwidth > 0))
        throw std::invalid_argument("model parameters");
    return latency+bytes/bandwidth;
}

int main() {
    const double batch = transfer(10000,10,100);
    const double separate = 100*transfer(100,10,100);
    assert(batch == 110 && separate == 1100);
    int rejected = 0;
    try { transfer(1,10,0); } catch(const std::invalid_argument&) { ++rejected; }
    try { transfer(1,10,-1); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected == 2);
    std::cout << "batch=" << batch << "us separate=" << separate << "us\n";
}
